"""Unital-Hodge folds at ALL a-degrees.  Hodge H = <H0, a> fixed.  Q0 is generated by q0 (Q0 = q0·k[q0]).
Generators g(f) = f - kappa(f), f = single-chaos words whose chaos-run is exactly q0.
kappa(f) = sum over optional left/right cuts of L1 a C(m) a R2, C: generator words (with >= 1 a) -> H0, arbitrary.
P defined recursively on the number of a's (kappa-terms strictly lower it). Fold <=> P(products of generators) = 0."""
import itertools, functools, sympy as sp
import fold as FD
from fold import MOD
class Gen:
    def __init__(self, S, C):
        self.S, self.C = S, C
        self.isQ = lambda i: S.side[i] == 'Q'
        self.one = [i for i in range(len(S.B)) if S.side[i] == 'H' and S.lev[i] == 0][0]
        Qs = sorted([i for i in range(len(S.B)) if self.isQ(i)], key=lambda i: S.lev[i]); self.q0 = Qs[0]
        # powers: q0^j in Q-basis, then invert to get q_k = sum_j T[k][j] q0^j
        q0p = S.B[self.q0][2].as_expr(); u = sp.symbols('u'); M = {}
        for j in range(1, len(Qs) + 1):
            try: M[j] = S.decompose(sp.expand(q0p**j))
            except AssertionError: break
        J = sorted(M); idx = {q: n for n, q in enumerate(Qs)}
        A = sp.zeros(len(J), len(J))
        for c, j in enumerate(J):
            for q, v in M[j].items():
                if idx[q] < len(J): A[idx[q], c] = v
        self.T = {}
        Ainv = A.inv_mod(MOD)
        for q in Qs[:len(J)]:
            r = idx[q]; self.T[q] = {J[c]: int(Ainv[c, r]) % MOD for c in range(len(J)) if int(Ainv[c, r]) % MOD}
        self._P = {}
    def mulw(self, w1, w2):
        out = {}
        for k, m in self.S.mul(w1[-1], w2[0]).items():
            w = w1[:-1] + (k,) + w2[1:]; out[w] = (out.get(w, 0) + m) % MOD
        return out
    def mul(self, A, B):
        out = {}
        for w1, c1 in A.items():
            for w2, c2 in B.items():
                for w, m in self.mulw(w1, w2).items(): out[w] = (out.get(w, 0) + c1 * c2 * m) % MOD
        return {w: c for w, c in out.items() if c}
    def kappa(self, f):
        i = [t for t, x in enumerate(f) if self.isQ(x)][0]; n = len(f) - 1; out = {}
        for j in [-1] + list(range(i)):
            for k in [n] + list(range(i, n)):
                m = f[j + 1:k + 1]
                if len(m) < 2: continue
                for b, v in self.C.get(m, {}).items():
                    w = f[:j + 1] + (b,) + f[k + 1:]; out[w] = (out.get(w, 0) + v) % MOD
        return {w: c for w, c in out.items() if c}
    def g(self, f):
        out = {f: 1}
        for w, c in self.kappa(f).items(): out[w] = (out.get(w, 0) - c) % MOD
        return {w: c for w, c in out.items() if c}
    def factors(self, w, powers):
        facs = []; cur = []; seenQ = False
        for t, x in enumerate(w):
            if not self.isQ(x): cur.append(x); continue
            for pc in range(powers[t]):
                if not seenQ: cur.append(self.q0); seenQ = True
                elif pc == 0: facs.append(tuple(cur)); cur = [self.one, self.q0]
                else: facs.append(tuple(cur)); cur = [self.q0]
        facs.append(tuple(cur)); return facs
    def P(self, w):
        if w in self._P: return self._P[w]
        qs = [t for t, x in enumerate(w) if self.isQ(x)]
        if len(w) == 1: res = {} if qs else {w: 1}
        elif not qs: res = {w: 1}
        else:
            res = {}
            for combo in itertools.product(*[list(self.T[w[t]].items()) for t in qs]):
                coef = 1; powers = {}
                for t, (j, c) in zip(qs, combo): coef = coef * c % MOD; powers[t] = j
                facs = self.factors(w, powers)
                pf = functools.reduce(self.mul, [{f: 1} for f in facs])
                pg = functools.reduce(self.mul, [self.g(f) for f in facs])
                diff = dict(pf)
                for ww, c in pg.items(): diff[ww] = (diff.get(ww, 0) - c) % MOD
                for ww, c in diff.items():
                    if c:
                        for k, v in self.P(ww).items(): res[k] = (res.get(k, 0) + coef * c * v) % MOD
            res = {k: v for k, v in res.items() if v}
        self._P[w] = res; return res
    def Pel(self, E):
        out = {}
        for w, c in E.items():
            for k, v in self.P(w).items(): out[k] = (out.get(k, 0) + c * v) % MOD
        return {k: v for k, v in out.items() if v}
def gen_words(S, maxruns, maxlev, q0):
    Hs = [i for i in range(len(S.B)) if S.side[i] == 'H' and S.lev[i] <= maxlev]
    for n in range(2, maxruns + 1):
        for pos in range(n):
            for hs in itertools.product(Hs, repeat=n - 1):
                w = hs[:pos] + (q0,) + hs[pos:]
                if sum(S.lev[x] for x in w) <= maxlev: yield w
def check(G, words, depth=2):
    bad = 0; tot = 0
    for combo in itertools.product(words, repeat=depth):
        try:
            r = G.Pel(functools.reduce(G.mul, [G.g(f) for f in combo])); tot += 1
            if r: bad += 1
        except FD.OutOfWindow: pass
    return bad, tot
